"""Build the shipment summary described in /app/docs/summary-format.md.

Usage: python3 summarize.py DATA_DIR OUT_FILE
Standard library only.
"""
import csv
import datetime as dt
import gzip
import io
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from fractions import Fraction

PRIORITY = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]

UNIT_FACTORS = {
    "kg": Fraction(1),
    "g": Fraction(1, 1000),
    "lb": Fraction("0.45359237"),
    "oz": Fraction("0.028349523125"),
}
UNIT_ALIASES = {"kgs": "kg", "kilogram": "kg", "kilograms": "kg", "gram": "g", "grams": "g",
                "lbs": "lb", "pound": "lb", "pounds": "lb", "ounce": "oz", "ounces": "oz"}

MONTHS = {m: i + 1 for i, m in enumerate(
    ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"])}


# --------------------------------------------------------------------------
# bytes and text
# --------------------------------------------------------------------------

def read_bytes(path):
    with open(path, "rb") as fh:
        b = fh.read()
    if b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    return b


def decode_text(b):
    if b[:3] == b"\xef\xbb\xbf":
        return b[3:].decode("utf-8", errors="replace")
    if b[:2] == b"\xff\xfe":
        return b[2:].decode("utf-16-le", errors="replace")
    if b[:2] == b"\xfe\xff":
        return b[2:].decode("utf-16-be", errors="replace")
    m = re.search(rb"(?im)^#[ \t]*charset[ \t]*:[ \t]*([A-Za-z0-9_.:-]+)", b[:8192])
    if m:
        name = m.group(1).decode("ascii")
        try:
            return b.decode(name)
        except (LookupError, UnicodeDecodeError):
            return b.decode("latin-1")
    try:
        return b.decode("utf-8")
    except UnicodeDecodeError:
        return b.decode("cp1252", errors="replace")


# --------------------------------------------------------------------------
# value parsing
# --------------------------------------------------------------------------

def norm_unit(u):
    if u is None:
        return None
    u = u.strip().lower()
    u = UNIT_ALIASES.get(u, u)
    return u if u in UNIT_FACTORS else None


def parse_number(s, decimal_comma=False):
    """Parse a number string exactly; returns Fraction or None."""
    if s is None:
        return None
    s = str(s).strip().replace("\u00a0", "").replace(" ", "")
    if not s:
        return None
    if decimal_comma:
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    try:
        return Fraction(s)
    except (ValueError, ZeroDivisionError):
        return None


WEIGHT_RE = re.compile(r"^\s*([-+]?[0-9][0-9.,\s]*|[-+]?\.[0-9]+)\s*([A-Za-z]+)?\s*$")


def parse_weight(raw, unit_hint, decimal_comma=False):
    """raw may carry its own unit suffix. unit_hint is the fallback unit.
    Returns kilograms as Fraction or None."""
    if raw is None:
        return None
    if isinstance(raw, (int, float)):
        raw = repr(raw)
    m = WEIGHT_RE.match(str(raw))
    if not m:
        return None
    num = parse_number(m.group(1), decimal_comma)
    if num is None:
        return None
    unit = norm_unit(m.group(2)) if m.group(2) else None
    if m.group(2) and unit is None:
        return None
    unit = unit or norm_unit(unit_hint) or "kg"
    return num * UNIT_FACTORS[unit]


ISO_DT_RE = re.compile(
    r"^(\d{4})-(\d{2})-(\d{2})[Tt ](\d{2}):(\d{2})(?::(\d{2})(?:[.,]\d+)?)?\s*(Z|z|[+-]\d{2}(?::?\d{2})?)?$")


def month_of(y, m):
    return "%04d-%02d" % (y, m)


def parse_ship_month(s, form=None):
    """Return 'YYYY-MM' (UTC month) for a ship date/time string, or None."""
    if s is None:
        return None
    s = str(s).strip()
    if not s:
        return None
    m = ISO_DT_RE.match(s)
    if m:
        y, mo, d, hh, mi = (int(m.group(i)) for i in range(1, 6))
        ss = int(m.group(6) or 0)
        try:
            t = dt.datetime(y, mo, d, hh, mi, ss)
        except ValueError:
            return None
        off = m.group(7)
        if off and off not in ("Z", "z"):
            sign = -1 if off[0] == "-" else 1
            digits = off[1:].replace(":", "")
            oh = int(digits[:2])
            om = int(digits[2:4]) if len(digits) > 2 else 0
            t = t - sign * dt.timedelta(hours=oh, minutes=om)
        return month_of(t.year, t.month)
    form = (form or "").strip().upper().replace(" ", "")
    # unambiguous shapes first
    m = re.match(r"^(\d{4})-(\d{1,2})-(\d{1,2})$", s)
    if m:
        return _ymd(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    m = re.match(r"^(\d{1,2})\s+([A-Za-z]{3})[A-Za-z]*\.?,?\s+(\d{4})$", s)
    if m and m.group(2).lower() in MONTHS:
        return _ymd(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    m = re.match(r"^(\d{1,2})\.(\d{1,2})\.(\d{4})$", s)
    if m:
        return _ymd(int(m.group(3)), int(m.group(2)), int(m.group(1)))
    m = re.match(r"^(\d{1,2})-(\d{1,2})-(\d{4})$", s)
    if m:
        a, b, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if form in ("MDY", "MM-DD-YYYY"):
            return _ymd(y, a, b)
        return _ymd(y, b, a)
    m = re.match(r"^(\d{1,2})/(\d{1,2})/(\d{4})$", s)
    if m:
        a, b, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if form in ("DD/MM/YYYY", "DMY"):
            return _ymd(y, b, a)
        return _ymd(y, a, b)
    m = re.match(r"^(\d{4})/(\d{1,2})/(\d{1,2})$", s)
    if m:
        return _ymd(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    if re.match(r"^\d+(\.\d+)?$", s):
        ip = s.split(".")[0]
        if form == "SERIAL":
            return _serial(int(ip))
        if len(ip) == 7 and form in ("YYYYDDD", ""):
            return _ydoy(int(ip[:4]), int(ip[4:]))
        if len(ip) == 8 and "." not in s:
            return _ymd(int(ip[:4]), int(ip[4:6]), int(ip[6:]))
        if len(ip) == 7:
            return _ydoy(int(ip[:4]), int(ip[4:]))
        return _serial(int(ip))
    return None


def _ymd(y, m, d):
    try:
        dt.date(y, m, d)
    except ValueError:
        return None
    return month_of(y, m)


def _serial(n):
    try:
        d = dt.date(1899, 12, 30) + dt.timedelta(days=n)
    except (OverflowError, ValueError):
        return None
    return month_of(d.year, d.month)


def _ydoy(y, doy):
    try:
        d = dt.date(y, 1, 1) + dt.timedelta(days=doy - 1)
    except (OverflowError, ValueError):
        return None
    return month_of(d.year, d.month)


def norm_status(s):
    if s is None:
        return ""
    return re.sub(r"[ \-]", "_", str(s).strip().lower())


COUNTED = {"delivered", "delivered_late"}

ID_RE = re.compile(r"^\s*SH\W*0*(\d+)\s*$", re.I)


def parse_id(s):
    if s is None:
        return None
    m = ID_RE.match(str(s))
    return int(m.group(1)) if m else None


NEW, COR, VOID = "new", "cor", "void"


def norm_type(s):
    s = (s or "").strip().lower()
    if s in ("v", "void"):
        return VOID
    if s in ("c", "cor", "corr", "correction", "amend", "amendment"):
        return COR
    return NEW


def make_record(num, typ, month, weight, status):
    return {"num": num, "type": typ, "month": month, "kg": weight, "status": norm_status(status)}


# --------------------------------------------------------------------------
# delimited text
# --------------------------------------------------------------------------

DELIM = {"east": ",", "lakeside": ",", "river": "\t", "west": ";", "harbor": "|"}
QUOTED = {"east", "lakeside"}
BASE_DATE = {"east": "YMD", "lakeside": "iso", "river": "MM/DD/YYYY", "west": "DD.MM.YYYY", "harbor": "iso"}

COLS = {
    "id": "id", "ref": "id",
    "type": "type", "kind": "type", "t": "type", "typ": "type", "rec": "type",
    "shipped": "shipped", "date": "shipped",
    "gross": "weight", "weight": "weight",
    "status": "status", "state": "status",
    "booked": "booked", "net": "net", "note": "note",
}
WCOL_RE = re.compile(r"^(gross|net|weight)_(kg|g|lb|oz)$")
STATUS_CODES = {"dlv": "delivered", "dll": "delivered_late", "can": "cancelled",
                "ret": "returned", "hld": "held"}


def header_names(fields):
    """Return canonical column list if all fields are column names, else None."""
    out = []
    for f in fields:
        k = f.strip().lower()
        if k in COLS:
            out.append((COLS[k], None))
        else:
            m = WCOL_RE.match(k)
            if not m:
                return None
            if m.group(1) == "net":
                out.append(("net", None))
            else:
                out.append(("weight", m.group(2)))
    return out


def split_row(buf, depot):
    d = DELIM[depot]
    if depot in QUOTED:
        try:
            rows = list(csv.reader([buf], delimiter=d))
        except csv.Error:
            return buf.split(d)
        return rows[0] if rows else []
    return buf.split(d)


def parse_delimited(text, depot):
    seq = None
    hdr = None
    date_form = BASE_DATE[depot]
    unit = None
    decimal_comma = depot == "west"
    records = []
    buf = None
    for line in text.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]
        if buf is None:
            if not line.strip():
                continue
            if line.startswith("#"):
                m = re.search(r"seq\s*[=:]\s*(\d+)", line, re.I)
                if m and seq is None:
                    seq = int(m.group(1))
                    continue
                m = re.match(r"^#\s*([^:=]+?)\s*:\s*(.*?)\s*$", line)
                if m:
                    name = m.group(1).strip().lower()
                    val = m.group(2)
                    if name in ("dates", "date format", "date", "dateformat", "date form"):
                        date_form = val.strip()
                    elif name in ("unit", "weight unit", "weight-unit"):
                        tok = re.split(r"[\s(]", val.strip(), maxsplit=1)[0]
                        u = norm_unit(tok)
                        if u:
                            unit = u
                        if "decimal comma" in val.lower():
                            decimal_comma = True
                        elif "decimal point" in val.lower() or "decimal dot" in val.lower():
                            decimal_comma = False
                continue
            buf = line
        else:
            buf += "\n" + line
        if depot in QUOTED and buf.count('"') % 2:
            continue
        row = split_row(buf, depot)
        buf = None
        h = header_names(row)
        if h is not None:
            hdr = h
            continue
        if hdr is None:
            continue
        rec = row_to_record(row, hdr, depot, date_form, unit, decimal_comma)
        if rec is not None:
            records.append(rec)
    return seq, records


def row_to_record(row, hdr, depot, date_form, unit_dir, decimal_comma):
    names = [n for n, _ in hdr]
    widx = names.index("weight") if "weight" in names else None
    row_unit = None
    if len(row) == len(hdr) + 1 and widx is not None:
        row_unit = norm_unit(row[widx + 1])
        if row_unit is not None:
            row = row[:widx + 1] + row[widx + 2:]
        else:
            # unit is somewhere else in the row: find a lone unit token
            for i, v in enumerate(row):
                if norm_unit(v) is not None and i != widx:
                    row_unit = norm_unit(v)
                    row = row[:i] + row[i + 1:]
                    break
            else:
                row = row[:len(hdr)]
    elif len(row) < len(hdr):
        row = row + [""] * (len(hdr) - len(row))
    elif len(row) > len(hdr):
        row = row[:len(hdr)]
    f = {}
    for (n, _), v in zip(hdr, row):
        f.setdefault(n, v)
    num = parse_id(f.get("id"))
    if num is None:
        return None
    typ = norm_type(f.get("type"))
    if typ == VOID:
        return make_record(num, VOID, None, None, None)
    field_unit = hdr[widx][1] if widx is not None else None
    raw_w = f.get("weight")
    wm = WEIGHT_RE.match(raw_w) if raw_w else None
    value_unit = norm_unit(wm.group(2)) if (wm and wm.group(2)) else None
    unit = field_unit or value_unit or row_unit or unit_dir or "kg"
    weight = parse_weight(raw_w, unit, decimal_comma)
    month = parse_ship_month(f.get("shipped"), date_form)
    status = f.get("status", "")
    if depot == "harbor" or status.strip().lower() in STATUS_CODES:
        status = STATUS_CODES.get(status.strip().lower(), status)
    return make_record(num, typ, month, weight, status)


# --------------------------------------------------------------------------
# fixed width
# --------------------------------------------------------------------------

FW = {
    "FW1": dict(length=42, type=(9, 10), id=(0, 9), shipped=(10, 17), weight=(17, 25), status=(25, 26),
                date="YYYYDDD", wunit="g", wdiv=1),
    "FW2": dict(length=43, type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26), status=(26, 27),
                date="YYYYMMDD", wunit="kg", wdiv=100),
    "FW3": dict(length=41, type=(16, 17), id=(0, 9), shipped=(9, 16), weight=(17, 24), status=(24, 25),
                date="YYYYDDD", wunit="lb", wdiv=10),
}
FW_BY_LEN = {v["length"]: k for k, v in FW.items()}
FW_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled", "R": "returned", "H": "held"}


def parse_fixed(text):
    seq = None
    layout = None
    records = []
    for line in text.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]
        if "\f" in line:
            continue
        if line.startswith("#"):
            m = re.match(r"^#LAYOUT\s+(\S+)", line)
            if m:
                layout = m.group(1).upper()
                continue
            m = re.match(r"^#SEQ\s+(\d+)", line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        if not line.strip():
            continue
        if re.match(r"^\s*SOUTH DEPOT\b", line):
            continue
        lay = FW_BY_LEN.get(len(line))
        if lay is None:
            lay = layout if layout in FW else None
            if lay is None:
                continue
            line = line.ljust(FW[lay]["length"])
        spec = FW[lay]
        sl = lambda k: line[spec[k][0]:spec[k][1]]
        num = parse_id(sl("id"))
        if num is None:
            continue
        typ = norm_type(sl("type"))
        if typ == VOID:
            records.append(make_record(num, VOID, None, None, None))
            continue
        month = parse_ship_month(sl("shipped"), spec["date"])
        w = sl("weight").strip()
        weight = None
        if w.isdigit():
            weight = Fraction(int(w), spec["wdiv"]) * UNIT_FACTORS[spec["wunit"]]
        status = FW_STATUS.get(sl("status").strip().upper(), sl("status"))
        records.append(make_record(num, typ, month, weight, status))
    return seq, records


# --------------------------------------------------------------------------
# XML
# --------------------------------------------------------------------------

def parse_xml(b):
    root = ET.fromstring(b)
    seq = None
    if root.get("seq") is not None:
        try:
            seq = int(str(root.get("seq")).strip())
        except ValueError:
            seq = None
    root_unit = norm_unit(root.get("weight-unit") or root.get("weight_unit") or root.get("unit"))
    records = []
    for el in root.iter("shipment"):
        num = parse_id(el.get("id"))
        if num is None:
            c = el.find("id")
            num = parse_id(c.text if c is not None else None)
        if num is None:
            continue
        typ = norm_type(el.get("type"))
        if typ == VOID:
            records.append(make_record(num, VOID, None, None, None))
            continue

        def val(name):
            if el.get(name) is not None:
                return el.get(name)
            c = el.find(name)
            return c.text if c is not None else None

        wel = el.find("weight")
        raw_w = wel.text if wel is not None else el.get("weight")
        unit = None
        if wel is not None:
            unit = norm_unit(wel.get("unit"))
        unit = unit or norm_unit(el.get("unit")) or root_unit or "kg"
        weight = parse_weight(raw_w, unit)
        month = parse_ship_month(val("shipped"))
        records.append(make_record(num, typ, month, weight, val("status")))
    return seq, records


# --------------------------------------------------------------------------
# JSON lines
# --------------------------------------------------------------------------

def parse_jsonl(text):
    seq = None
    records = []

    def handle(o):
        nonlocal seq
        if not isinstance(o, dict):
            return
        if "meta" in o and isinstance(o["meta"], dict) and "id" not in o:
            s = o["meta"].get("seq")
            if s is not None and seq is None:
                try:
                    seq = int(s)
                except (TypeError, ValueError):
                    pass
            return
        num = parse_id(o.get("id"))
        if num is None:
            return
        typ = norm_type(o.get("kind"))
        if typ == VOID:
            records.append(make_record(num, VOID, None, None, None))
            return
        raw_w, unit = None, None
        for k, v in o.items():
            m = re.match(r"^weight_(kg|g|lb|oz)$", k, re.I)
            if m:
                raw_w, unit = v, m.group(1).lower()
                break
        else:
            if "weight" in o:
                raw_w = o["weight"]
                unit = norm_unit(o.get("unit")) or "kg"
        weight = parse_weight(raw_w, unit)
        month = parse_ship_month(o.get("shipped_at") or o.get("shipped"))
        records.append(make_record(num, typ, month, weight, o.get("status")))

    for line in text.split("\n"):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        try:
            v = json.loads(line, parse_float=str, parse_int=str)
        except ValueError:
            continue
        if isinstance(v, list):
            for o in v:
                handle(o)
        else:
            handle(v)
    return seq, records


# --------------------------------------------------------------------------
# driver
# --------------------------------------------------------------------------

def parse_export(path, depot):
    b = read_bytes(path)
    if depot == "central":
        return parse_xml(b)
    text = decode_text(b)
    if depot == "north":
        return parse_jsonl(text)
    if depot == "south":
        return parse_fixed(text)
    if depot in DELIM:
        return parse_delimited(text, depot)
    # unknown depot: sniff
    s = text.lstrip()
    if s.startswith("<"):
        return parse_xml(b)
    if s.startswith("{") or s.startswith("["):
        return parse_jsonl(text)
    return None, []


def build(data_dir):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0]
        try:
            seq, recs = parse_export(path, depot)
        except Exception as e:  # keep going; report on stderr
            print("warning: cannot read %s: %s" % (name, e), file=sys.stderr)
            seq, recs = None, []
        exports.setdefault(depot, []).append((seq, name, recs))

    corrections = 0
    resends = 0
    current = {}  # depot -> {num: record}
    for depot, exps in exports.items():
        exps.sort(key=lambda e: (e[0] is None, e[0] if e[0] is not None else 0, e[1]))
        cur = {}
        for _, _, recs in exps:
            for r in recs:
                n = r["num"]
                if r["type"] == NEW:
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["type"] == COR:
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur

    order = [d for d in PRIORITY if d in current] + sorted(d for d in current if d not in PRIORITY)
    kept = {}
    seen_in = {}
    for depot in order:
        for n, r in current[depot].items():
            seen_in[n] = seen_in.get(n, 0) + 1
            if n not in kept:
                kept[n] = (depot, r)
    handovers = sum(1 for c in seen_in.values() if c > 1)

    dep_tot = {d: [0, Fraction(0)] for d in exports}
    mon_tot = {}
    for n, (depot, r) in kept.items():
        if r["status"] not in COUNTED:
            continue
        w = r["kg"] if r["kg"] is not None else Fraction(0)
        if r["kg"] is None or r["month"] is None:
            print("warning: shipment %s has unreadable weight/date" % n, file=sys.stderr)
        dep_tot[depot][0] += 1
        dep_tot[depot][1] += w
        if r["month"] is not None:
            m = mon_tot.setdefault(r["month"], [0, Fraction(0)])
            m[0] += 1
            m[1] += w

    return {
        "depots": {d: {"shipments": dep_tot[d][0], "total_kg": rnd(dep_tot[d][1])} for d in sorted(dep_tot)},
        "months": {m: {"shipments": mon_tot[m][0], "total_kg": rnd(mon_tot[m][1])} for m in sorted(mon_tot)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }


def rnd(x):
    """Round an exact Fraction to 2 decimals (half up) and return a float."""
    cents = (x * 100 + Fraction(1, 2)).__floor__()
    return float("%d.%02d" % divmod(cents, 100)) if cents >= 0 else -float("%d.%02d" % divmod(-cents, 100))


def main(argv):
    if len(argv) != 3:
        print("usage: summarize.py DATA_DIR OUT_FILE", file=sys.stderr)
        return 2
    result = build(argv[1])
    out_dir = os.path.dirname(os.path.abspath(argv[2]))
    os.makedirs(out_dir, exist_ok=True)
    with open(argv[2], "w", encoding="utf-8") as fh:
        json.dump(result, fh, indent=2)
        fh.write("\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
